   133	/**
   134	 * Returns whether or not an IOU report contains expenses in a different currency
   135	 * that are either created or cancelled offline, and thus haven't been converted to the report's currency yet
   136	 */
   137	function isIOUReportPendingCurrencyConversion(iouReport: Report): boolean {
   138	    const reportTransactions = getReportTransactions(iouReport.reportID);
   139	    const pendingRequestsInDifferentCurrency = reportTransactions.filter((transaction) => transaction.pendingAction && getCurrency(transaction) !== iouReport.currency);
   140	    return pendingRequestsInDifferentCurrency.length > 0;
   141	}
