   146	function isValidMoneyRequestType(iouType: string): boolean {
   147	    const moneyRequestType: string[] = [
   148	        CONST.IOU.TYPE.REQUEST,
   149	        CONST.IOU.TYPE.SUBMIT,
   150	        CONST.IOU.TYPE.SPLIT,
   151	        CONST.IOU.TYPE.SPLIT_EXPENSE,
   152	        CONST.IOU.TYPE.SEND,
   153	        CONST.IOU.TYPE.PAY,
   154	        CONST.IOU.TYPE.TRACK,
   155	        CONST.IOU.TYPE.INVOICE,
   156	        CONST.IOU.TYPE.CREATE,
   157	    ];
   158	
   159	    return moneyRequestType.includes(iouType);
   160	}
