   162	/**
   163	 * Inserts a newly selected tag into the already existing tags like a string
   164	 *
   165	 * @param transactionTags - currently selected tags for a report
   166	 * @param tag - a newly selected tag, that should be added to the transactionTags
   167	 * @param tagIndex - the index of a tag list
   168	 * @returns
   169	 */
   170	function insertTagIntoTransactionTagsString(transactionTags: string, tag: string, tagIndex: number): string {
   171	    const tagArray = getTagArrayFromName(transactionTags);
   172	    tagArray[tagIndex] = tag;
   173	
   174	    while (tagArray.length > 0 && !tagArray.at(-1)) {
   175	        tagArray.pop();
   176	    }
   177	
   178	    return tagArray.map((tagItem) => tagItem.trim()).join(CONST.COLON);
   179	}
