   181	function isMovingTransactionFromTrackExpense(action?: IOUAction) {
   182	    if (action === CONST.IOU.ACTION.SUBMIT || action === CONST.IOU.ACTION.SHARE || action === CONST.IOU.ACTION.CATEGORIZE) {
   183	        return true;
   184	    }
   185	
   186	    return false;
   187	}
