   189	function shouldUseTransactionDraft(action: IOUAction | undefined, type?: IOUType) {
   190	    return action === CONST.IOU.ACTION.CREATE || type === CONST.IOU.TYPE.SPLIT_EXPENSE || isMovingTransactionFromTrackExpense(action);
   191	}
