   197	    const initialAttendee: Attendee = {
   198	        email: currentUser?.login ?? '',
   199	        login: currentUser?.login ?? '',
   200	        displayName: currentUser.displayName ?? '',
   201	        avatarUrl: currentUser.avatar?.toString() ?? '',
   202	        accountID: currentUser.accountID,
   203	        text: currentUser.login,
   204	        selected: true,
   205	        reportID,
   206	    };
   207	
   208	    return [initialAttendee];
   209	}
